// Second hand-drawn brush pack: the Janssonius 17th-century cartography
// brush set (CC0 / public domain, by K.M. Alexander) -- embedded as base64
// data, same approach as brush-stamps.js. Adds engraved-hachure mountains
// and hills, a period compass rose, ships, and a few flavor icons.

Object.assign(STAMP_SOURCES, {
  jans_mountain_range: { w: 180, h: 58, data: 'data:image/png;base64,' },
  jans_hill: { w: 180, h: 31, data: 'data:image/png;base64,' },
  jans_rocks: { w: 60, h: 37, data: 'data:image/png;base64,' },
  jans_town: { w: 47, h: 52, data: 'data:image/png;base64,' },
  jans_city: { w: 69, h: 93, data: 'data:image/png;base64,' },
  jans_camp: { w: 38, h: 20, data: 'data:image/png;base64,' },
  jans_ship: { w: 180, h: 106, data: 'data:image/png;base64,' },
  jans_shipwreck: { w: 69, h: 48, data: 'data:image/png;base64,' },
  jans_oasis: { w: 160, h: 57, data: 'data:image/png;base64,' },
  jans_hazard: { w: 21, h: 22, data: 'data:image/png;base64,' },
  jans_wind_cherub: { w: 180, h: 118, data: 'data:image/png;base64,' },
  jans_compass: { w: 180, h: 123, data: 'data:image/png;base64,' },
  jans_tree: { w: 26, h: 39, data: 'data:image/png;base64,' },
  jans_forest_mass: { w: 180, h: 116, data: 'data:image/png;base64,' },
  jans_shallow_dots: { w: 51, h: 47, data: 'data:image/png;base64,' },
  jans_field: { w: 180, h: 116, data: 'data:image/png;base64,' },
});

Object.assign(STAMP_IMAGES, {});
const janssoniusReady = Promise.all(Object.keys(STAMP_SOURCES)
  .filter((key) => !STAMP_IMAGES[key])
  .map((key) => new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve();
    img.onerror = () => resolve();
    img.src = STAMP_SOURCES[key].data;
    STAMP_IMAGES[key] = img;
  })));
